%[text] # Build input signal trace
%[text] Generate data.
signal_design_matrix = SignalTool2.generateSignalDesignMatrixFromTraceProperties(...
  RandomSeed = 25, ...
  FInitialValue = 0, ...
  XInitialFlatLength = 100, ...
  XInitialTransitionLength = 20, ...
  NumTransitions = 10, ...
  TransitionXRange = [1 10], ...
  FlatXRange = [10 300], ...
  FRange = [40 100], ...
  XFinalTransitionLength = 20, ...
  XFinalFlatLength = 10, ...
  FFinalValue = 0 );

data_table = SignalTool2.getXYVectorsFromSignalDesignMatrix(signal_design_matrix);

t = data_table.X;
f = data_table.Y;

fig = figure; %[output:4510eefd]
fig.Position(3:4) = [900 300];  % width height %[output:4510eefd]
SignalTool2.plotLookupTable1D(t, f, InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:4510eefd]
%%
%[text] Set the generated data to the target block in the target model.
model_name = "BEVController_Inputs_Random_refsub";
load_system(model_name)

block_path = model_name + "/Vehicle speed reference";

% Target block is Simulink 1D Lookup Table.
set_param(block_path, "Table", CodeTool1.stringify(f))
set_param(block_path, "BreakpointsForDimension1", CodeTool1.stringify(t))
